#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

static uint64_t mulmod(uint64_t a, uint64_t b, uint64_t mod) {
    __uint128_t res = ( __uint128_t ) a * b;
    return (uint64_t)(res % mod);
}

static uint64_t powmod(uint64_t base, uint64_t exp, uint64_t mod) {
    uint64_t result = 1 % mod;
    base %= mod;
    while (exp) {
        if (exp & 1) result = mulmod(result, base, mod);
        base = mulmod(base, base, mod);
        exp >>= 1;
    }
    return result;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }
    char *endptr = NULL;
    long long n_ll = strtoll(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (n_ll > 0xBFA17DC6LL) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    if (n_ll < 2) {
        puts("NOT_PRIME");
        return 0;
    }
    uint64_t n = (uint64_t)n_ll;
    const uint64_t bases[] = {2, 3, 5, 7, 11, 13};
    // trial division by small primes
    for (size_t i = 0; i < sizeof(bases)/sizeof(bases[0]); ++i) {
        uint64_t a = bases[i];
        if (n % a == 0) {
            if (n == a) continue; // n is the prime itself
            puts("NOT_PRIME");
            return 0;
        }
    }
    // write n-1 as d * 2^s with d odd
    uint64_t d = n - 1;
    unsigned int s = 0;
    while ((d & 1) == 0) {
        d >>= 1;
        ++s;
    }
    // Miller-Rabin test for each base
    for (size_t i = 0; i < sizeof(bases)/sizeof(bases[0]); ++i) {
        uint64_t a = bases[i];
        uint64_t x = powmod(a, d, n);
        if (x == 1 || x == n - 1) continue;
        int r;
        for (r = 1; r < (int)s; ++r) {
            x = mulmod(x, x, n);
            if (x == n - 1) break;
        }
        if (r == (int)s) {
            puts("NOT_PRIME");
            return 0;
        }
    }
    puts("PRIME");
    return 0;
}
